others=[c for c in cls if c not in (58,65)]
def pdir(c, comps, ort):
    keep=[c]+list(comps)
    A=np.stack([M[cmap[k]]-c_mid for k in others if k not in keep])
    Qk,_=np.linalg.qr(A.T)
    d=M[cmap[c]]-np.mean(np.stack([M[cmap[k]] for k in comps]),axis=0)
    v=DK@d; v=v-Qk@(Qk.T@v)
    for w in ort: v=v-w*float(w@v)
    return unit(v)
