res={}
for a in [4.5,5.0,5.5,6.0,6.5]:
    for b in [2.0,2.5,3.0,3.5]:
        for c65 in [0.0,1.5,3.0]:
            Wn2=Worig.copy(); bn2=b0.copy()
            Wn2[58]+=a*u+b*u2_58; Wn2[65]-=a*u+c65*u2_65
