            pr=(H@Wn2.T+bn2).argmax(1)
            res[(a,b,c65)]=(round(float((pr[m]==lab[m]).mean()),3), round(float((pr==lab).mean()),4),
                            int((pr[o]!=lab[o]).sum()))
top=sorted(res.items(), key=lambda kv:(-kv[1][0], -kv[1][1]))[:12]
for k,v in top: print(k,v)
